def _trigger_text(ex: TrainExample) -> str:
    """The triggering (last) user turn — the stable per-example dedup/seed key."""
    return next(
        (str(m.get("content", "")) for m in reversed(ex.messages) if m.get("role") == "user"), ""
    )

def _distractor_specs(
    target: ToolSchema, ex: TrainExample, spec_by_name: dict[str, ToolSchema]
) -> list[FunctionSpec]:
    """Function specs for sibling tools shown beside ``target`` (target excluded).

    Prefers same-capability siblings (the hard distractors — a model that can
    pick ``make_payment`` over ``list_charges`` has learned selection, not just
    arg-shaping), then any other live tool. The count + ordering are derived
    deterministically from the example's trigger turn so a rebuild is byte-stable.
    """
    siblings = sorted(
        (t for n, t in spec_by_name.items() if n != target.name),
        key=lambda t: (t.capability_key != target.capability_key, t.name),
    )
    if not siblings:
        return []
    seed = int.from_bytes(
        hashlib.blake2b(f"{target.name}|{_trigger_text(ex)}".encode(), digest_size=8).digest(),
        "big",
    )
    k = min(len(siblings), rand.Generator(seed, backend="stdlib").randint(1, _MAX_DISTRACTORS))
    return [tool_spec(t) for t in siblings[:k]]

