def tool_spec(tool: ToolSchema) -> FunctionSpec:
    """OpenAI function spec for a tool — the ``tools`` entry beside ``messages``."""
    return {
        "type": "function",
        "function": {
            "name": tool.name,
            "description": tool.description,
            "parameters": tool.args_schema or {"type": "object", "properties": {}},
        },
    }
